\begin{figure}[htbp]
\centering
\includegraphics[width=\linewidth]{figures/fig_tileworld_belief.pdf}
\caption{Belief evolution within an EFE episode on the $6{\times}6$ Tileworld. Panels (a)--(g) show belief probability over the 36 grid cells on a shared square-root color scale (colorbar, darker = higher probability). Black outlines mark the cell group queried by each scan, each panel's title reports that scan's noisy binary readout as $\mathrm{obs}{=}\mathrm{A}$ or $\mathrm{obs}{=}\mathrm{B}$ naming which half of the queried group the signal favors, and the black-edged white star marks the target tile in every panel. Belief concentrates toward the target, and in the final panel a black-stroked white ring marks the committed cell.}
\label{fig:tw_belief}
\Description{Two rows of six-by-six grid heatmaps labeled (a) through (g), with a horizontal colorbar decoding belief probability on a square-root color scale. Panel (a) is the uniform prior. Panels (b) through (f) outline the queried cell group in black while belief concentrates, with each panel's title also reporting the noisy binary outcome of that scan as obs equals A or obs equals B, naming which half of the outlined group the scan's signal favors, and with one cell reaching 0.47 in panel (e) and the cell beside it reaching a dark red 0.73 in panel (f). A black-edged white star marks the target tile in every panel. Panel (g) shows the collect step, where a black-stroked white ring around the star-marked target indicates a correct commit.}
\end{figure}

